package com.edubridge.chat;
import com.edubridge.backend.user.entity.User; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="chat_servers") public class CommunityServer { @Id @GeneratedValue private UUID id; @Column(nullable=false,length=80) private String name; @Column(length=300) private String description; @ManyToOne(optional=false) private User owner; @Column(nullable=false) private Instant createdAt=Instant.now(); protected CommunityServer(){} public CommunityServer(String n,String d,User o){name=n;description=d;owner=o;} public UUID getId(){return id;} public String getName(){return name;} public String getDescription(){return description;} public User getOwner(){return owner;} }
